pkill -9 -x mpvpaper
timeout 2 pidwait -x mpvpaper

for monitor in $(hyprctl monitors -j | jq -r '.[] | .name'); do
    mpvpaper -o 'no-audio loop hwdec=auto scale=bilinear interpolation=no video-sync=display-resample panscan=1.0 video-scale-x=1.0 video-scale-y=1.0 video-align-x=0.5 video-align-y=0.5 load-scripts=no' "$monitor" '@HOME@/Pictures/Wallpapers/clip.mp4' &
done
